import functools

def semver_sort(versions):
    def parse(v):
        core = v
        build = None
        if '+' in core:
            core, build = core.split('+', 1)
        pre = None
        if '-' in core:
            core, pre = core.split('-', 1)
        parts = core.split('.')
        major, minor, patch = (int(p) for p in parts)
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def compare(a, b):
        va = parse(a)
        vb = parse(b)
        if va[0] != vb[0]:
            return -1 if va[0] < vb[0] else 1
        if va[1] != vb[1]:
            return -1 if va[1] < vb[1] else 1
        if va[2] != vb[2]:
            return -1 if va[2] < vb[2] else 1
        pre_a, pre_b = va[3], vb[3]
        if pre_a is None and pre_b is None:
            return 0
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1
        for ia, ib in zip(pre_a, pre_b):
            if ia == ib:
                continue
            ia_num = ia.isdigit()
            ib_num = ib.isdigit()
            if ia_num and ib_num:
                na, nb = int(ia), int(ib)
                if na != nb:
                    return -1 if na < nb else 1
                continue
            if ia_num and not ib_num:
                return -1
            if not ia_num and ib_num:
                return 1
            if ia != ib:
                return -1 if ia < ib else 1
        if len(pre_a) != len(pre_b):
            return -1 if len(pre_a) < len(pre_b) else 1
        return 0

    indexed = list(enumerate(versions))
    def cmp_wrapped(x, y):
        c = compare(x[1], y[1])
        if c != 0:
            return c
        return x[0] - y[0]
    indexed.sort(key=functools.cmp_to_key(cmp_wrapped))
    return [v for i, v in indexed]

